        if ((declaration?.kind !== SyntaxKind.PropertyDeclaration) || (owner?.kind !== SyntaxKind.ClassDeclaration) || (owner.name?.text !== 'BaseExchange')) { return undefined; }
        return this.GO_MARKET_TABLES[node.name.text];
