        if ((callee === 'createSafeDictionary') && (args.length <= 1)) { return `${left} = map[string]any{}`; }
        if ((callee === 'indexBySafe') && (args.length === 2)) { return `${left} = this.IndexBy(${args.map((a) => this.printNode(a, 0)).join(', ')})`; }
        const valueNode = ((callee === 'mapToSafeMap') && (args.length === 1)) ? this.goUnwrapParenthesizedNode(args[0]) : right;
        const text = this.printNode(valueNode, 0).trim();
